import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·1","description":"易小帖 - 卷一·1","frontmatter":{"title":"卷一·1","description":"易小帖 - 卷一·1"},"headers":[],"relativePath":"zh/classics/yixiaotie/001.md","filePath":"zh/classics/yixiaotie/001.md"}'),o={name:"zh/classics/yixiaotie/001.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·1",tabindex:"-1"},[r("卷一·1 "),e("a",{class:"header-anchor",href:"#卷一·1","aria-label":"Permalink to “卷一·1”"},"​")],-1),e("p",null,"上系雲：剛柔相推而生變化。又雲：變化者進退之象也。夫剛柔者陰陽也，自畫卦以後陰爻與陽爻皆屬一定，有何相推？有何變化？殊不知，變化者進退之象，則文王繋詞，左氏占驗，全在乎進退諸陰陽之畫而變化之矣。故又曰：化而裁之存乎變，推而行之存乎通，神而明之存乎其人。此推易之法也。蓋推易者，往來進退之事也。是以易曰：憧憧往來。子曰：日往則月來，月往則日來，日月相推而明生焉，寒往則暑來，暑往則寒來，寒暑相推而歲成焉。故又曰：夫易彰往而察來，是以六十四卦於泰否二聚卦獨曰小往大來、大往小來。立往來大義，而其中之往來者亹亹焉，非推易乎。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
